"""Iceberg width measurement (#2146) — scratch, not committed.

gen <shape> <rows>        build the table (host, own process)
run <shape> <rows> [warm] measure peak RSS over the post-import baseline (rig)
"""

from __future__ import annotations

import json
import os
import resource
import sys
import time
from pathlib import Path

ROOT = Path(os.environ.get("PERF_DATA_DIR", Path.home() / ".cache" / "dataq-perf")) / "iceberg_width"
CONFIG = {
    "catalog_name": "width",
    "catalog_type": "sql",
    "catalog_uri": f"sqlite:///{ROOT}/catalog.db",
    "warehouse": f"file://{ROOT}/warehouse",
}
CHUNK = 250_000


def _col(shape: str, rows: int, rng, i: int):
    import numpy as np
    import pyarrow as pa

    kind, _, arg = shape.partition("_")
    if kind == "int64":
        return pa.array(rng.integers(0, 1 << 40, rows), pa.int64())
    if kind == "int32":
        return pa.array(rng.integers(0, 1 << 30, rows, dtype="int32"), pa.int32())
    if kind == "float64":
        return pa.array(rng.random(rows), pa.float64())
    if kind == "bool":
        return pa.array(rng.random(rows) > 0.5, pa.bool_())
    if kind == "date":
        return pa.array(rng.integers(0, 20000, rows, dtype="int32"), pa.int32()).cast(pa.date32())
    if kind == "ts":
        return pa.array(rng.integers(0, 1 << 50, rows), pa.int64()).cast(pa.timestamp("us"))
    if kind == "tstz":
        return pa.array(rng.integers(0, 1 << 50, rows), pa.int64()).cast(pa.timestamp("us", tz="UTC"))
    if kind == "decimal":
        import decimal

        ints = rng.integers(0, 10**9, rows)
        return pa.array([decimal.Decimal(int(v)).scaleb(-2) for v in ints], pa.decimal128(18, 2))
    if kind == "rand":  # random strings of `arg` chars (high entropy)
        n = int(arg)
        alphabet = np.frombuffer(b"REDACTED", dtype="S1")
        chars = alphabet[rng.integers(0, len(alphabet), rows * n)].tobytes()
        return pa.array([chars[j * n : (j + 1) * n].decode() for j in range(rows)], pa.large_string())
    if kind == "lowcard":  # `arg` = length; 20 distinct values
        n = int(arg)
        values = [(f"v{k:02d}-" + "x" * n)[:n] for k in range(20)]
        idx = rng.integers(0, 20, rows)
        return pa.array([values[j] for j in idx], pa.large_string())
    if kind == "bin":
        n = int(arg)
        return pa.array([os.urandom(n) for _ in range(rows)], pa.large_binary())
    if kind == "list":
        offsets = np.arange(0, rows * 3 + 1, 3, dtype="int64")
        return pa.LargeListArray.from_arrays(pa.array(offsets), pa.array(rng.integers(0, 1000, rows * 3)))
    if kind == "struct":
        return pa.StructArray.from_arrays(
            [pa.array(rng.integers(0, 1000, rows)), pa.array(rng.random(rows))], names=["a", "b"]
        )
    raise SystemExit(f"unknown shape {shape}")


def _spec(shape_spec: str) -> tuple[str, int]:
    # "<shape>x<cols>" e.g. rand_20x8
    shape, _, cols = shape_spec.rpartition("x")
    return shape, int(cols)


def _name(shape_spec: str, rows: int) -> str:
    return f"w.{shape_spec.replace('-', '_')}_{rows}"


def _catalog():
    from pyiceberg.catalog.sql import SqlCatalog
    from pyiceberg.exceptions import NamespaceAlreadyExistsError

    (ROOT / "warehouse").mkdir(parents=True, exist_ok=True)
    cat = SqlCatalog("width", uri=CONFIG["catalog_uri"], warehouse=CONFIG["warehouse"])
    try:
        cat.create_namespace("w")
    except NamespaceAlreadyExistsError:
        pass
    return cat


def gen(shape_spec: str, rows: int) -> None:
    import numpy as np
    import pyarrow as pa
    from pyiceberg.exceptions import NoSuchTableError

    shape, cols = _spec(shape_spec)
    cat = _catalog()
    name = _name(shape_spec, rows)
    try:
        cat.drop_table(name)
    except NoSuchTableError:
        pass
    table = None
    written = 0
    while written < rows:
        n = min(CHUNK, rows - written)
        rng = np.random.default_rng(written + 1)
        data = {
            "k1": pa.array(np.arange(written, written + n), pa.int64()),
            "k2": pa.array(rng.integers(1, 21, n), pa.int64()),
        }
        for i in range(cols):
            data[f"c{i}"] = _col(shape, n, rng, i)
        arrow = pa.table(data)
        if table is None:
            table = cat.create_table(name, schema=arrow.schema)
        table.append(arrow)
        written += n
    files = table.inspect.data_files()
    print(name, rows, sum(files.column("file_size_in_bytes").to_pylist()) / 2**20, "MiB")


def _rss_now_kib() -> int:
    with open("/proc/self/status") as fh:
        for line in fh:
            if line.startswith("VmRSS:"):
                return int(line.split()[1])
    return 0


def run(shape_spec: str, rows: int, warm: bool) -> None:
    from backend.app.core.config import get_settings
    from backend.app.datasources import iceberg as iceberg_mod
    from backend.app.datasources.base import CheckSpec

    get_settings()
    specs = [
        CheckSpec("expect_column_values_to_be_unique", {"column": "k1"}),
        CheckSpec("expect_column_values_to_not_be_null", {"column": "k2"}),
        CheckSpec("expect_column_values_to_be_between", {"column": "k2", "min_value": 1, "max_value": 20}),
        CheckSpec("expect_column_values_to_not_be_null", {"column": "c0"}),
        CheckSpec("expect_column_values_to_not_be_null", {"column": "c1"}),
    ]
    runner = iceberg_mod.IcebergCheckRunner(
        config=iceberg_mod.IcebergConfig.model_validate(CONFIG), secret=None
    )
    identifier = _name(shape_spec, rows)
    table = runner._load_table(identifier)
    scan = iceberg_mod.planned_scan(table)
    arrow_schema = table.schema().as_arrow()
    if warm:
        runner.run_checks(table=_name(shape_spec, 1000), schema=None, checks=specs)
    base_max = resource.getrusage(resource.RUSAGE_SELF).ru_maxrss
    base_now = _rss_now_kib()
    started = time.perf_counter()
    outcome = runner.run_checks(table=identifier, schema=None, checks=specs)
    wall = time.perf_counter() - started
    peak = resource.getrusage(resource.RUSAGE_SELF).ru_maxrss
    print(
        json.dumps(
            {
                "shape": shape_spec,
                "rows": rows,
                "warm": warm,
                "types": [str(f.type) for f in arrow_schema],
                "file_mib": round(sum(scan.bytes_by_format.values()) / 2**20, 1),
                "base_now_mib": round(base_now / 1024, 1),
                "base_max_mib": round(base_max / 1024, 1),
                "peak_mib": round(peak / 1024, 1),
                "delta_mib": round((peak - base_now) / 1024, 1),
                "wall_s": round(wall, 2),
                "passed": sum(1 for c in outcome.checks if c.success),
                "errored": sum(1 for c in outcome.checks if c.errored),
            }
        ),
        flush=True,
    )


if __name__ == "__main__":
    cmd, shape_spec, rows = sys.argv[1], sys.argv[2], int(sys.argv[3])
    if cmd == "gen":
        gen(shape_spec, rows)
    else:
        run(shape_spec, rows, len(sys.argv) > 4 and sys.argv[4] == "warm")

