import json
import sys

import pyarrow as pa

samples = json.load(open(sys.argv[1] if len(sys.argv) > 1 else "samples.json"))


def parse(t: str):
    return {
        "int64": pa.int64(),
        "int32": pa.int32(),
        "double": pa.float64(),
        "bool": pa.bool_(),
        "date32[day]": pa.date32(),
        "timestamp[us]": pa.timestamp("us"),
        "timestamp[us, tz=UTC]": pa.timestamp("us", tz="UTC"),
        "decimal128(18, 2)": pa.decimal128(18, 2),
    }.get(t)


def model(p):
    def cell(t, nb):
        at = parse(t)
        if at is None:
            return p["vb"] + p["vk"] * nb
        if pa.types.is_boolean(at):
            return p["bool"]
        if pa.types.is_decimal(at):
            return p["dec"]
        if at.bit_width <= 32:
            return p["narrow"]
        return p["wide"]

    return cell


def run(p, show=False):
    cell = model(p)
    ratios = []
    for key, s in samples.items():
        row = sum(cell(t, nb) for t, nb in s["cols"].values())
        est = (p["I"] * 2**20 + s["rows"] * row) / 2**20
        r = est / s["measured"]
        ratios.append(r)
        if show:
            print(f"{key:24s} meas {s['measured']:7.1f} est {est:7.1f} ratio {r:5.2f}")
    return min(ratios), max(ratios)


P = dict(I=float(sys.argv[2]) if len(sys.argv) > 2 else 190, bool=11, narrow=18, wide=33, dec=40, vb=16, vk=3.0)
for k in sys.argv[3:]:
    name, val = k.split("=")
    P[name] = float(val)
print(P, run(P, show=True))

